 22	public class Application {
 23	    private static final Gson gson = new Gson();
 24	    private static Javalin app;
 25	
 26	    public static void main(String[] args) {
 27	        Database.initializeSchema();
 28	
 29	        RoomRepository roomRepository = new RoomRepository();
 30	        ReservationRepository reservationRepository = new ReservationRepository();
 31	        MessageRepository messageRepository = new MessageRepository();
 32	        ReservationService reservationService = new ReservationService(roomRepository, reservationRepository, messageRepository);
 33	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 34	
 35	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 36	
 37	        app = Javalin.create().start(port);
 38	
 39	        setupRoutes(app, reservationService, reportService, roomRepository, reservationRepository, messageRepository);
 40	
 41	        System.out.println("Pousada Maré Alta started on port " + port);
 42	    }
