 44	    private static void setupRoutes(Javalin app, ReservationService reservationService, ReportService reportService,
 45	                                     RoomRepository roomRepository, ReservationRepository reservationRepository,
 46	                                     MessageRepository messageRepository) {
 47	        app.get("/rooms", ctx -> {
 48	            try {
 49	                var rooms = roomRepository.findAll();
 50	                ctx.json(rooms.stream().map(RoomResponse::from).toList());
 51	            } catch (Exception e) {
 52	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
 53	            }
 54	        });
 55	
 56	        app.post("/reservations", ctx -> {
 57	            try {
 58	                ReservationRequest req = ctx.bodyAsClass(ReservationRequest.class);
 59	
 60	                if (req.roomNumber == 0 || req.guestName == null || req.guestEmail == null ||
 61	                    req.guestCpf == null || req.checkIn == null || req.checkOut == null ||
 62	                    req.ratePlan == null) {
 63	                    handleError(ctx, "INVALID_REQUEST", "Campo obrigatório ausente", 400);
 64	                    return;
 65	                }
 66	
 67	                try {
 68	                    LocalDate checkIn = LocalDate.parse(req.checkIn);
 69	                    LocalDate checkOut = LocalDate.parse(req.checkOut);
 70	
 71	                    var reservation = reservationService.createReservation(
 72	                        req.roomNumber,
 73	                        req.guestName,
 74	                        req.guestEmail,
 75	                        req.guestCpf,
 76	                        checkIn,
 77	                        checkOut,
 78	                        req.guests,
 79	                        req.ratePlan,
 80	                        req.companyCode
 81	                    );
 82	
 83	                    ctx.status(201).json(ReservationResponse.from(reservation));
 84	                } catch (DateTimeParseException e) {
 85	                    handleError(ctx, "INVALID_REQUEST", "Formato de data inválido", 400);
 86	                }
 87	            } catch (ApiException e) {
 88	                handleError(ctx, e.getCode(), e.getMessage(), e.getHttpStatus());
 89	            } catch (Exception e) {
 90	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
 91	            }
 92	        });
 93	
 94	        app.get("/reservations/{id}", ctx -> {
 95	            try {
 96	                long id = Long.parseLong(ctx.pathParam("id"));
 97	                var reservation = reservationService.getReservation(id);
 98	                ctx.json(ReservationResponse.from(reservation));
 99	            } catch (ApiException e) {
100	                handleError(ctx, e.getCode(), e.getMessage(), e.getHttpStatus());
101	            } catch (Exception e) {
102	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
103	            }
104	        });
105	
106	        app.post("/reservations/{id}/confirmation", ctx -> {
107	            try {
108	                long id = Long.parseLong(ctx.pathParam("id"));
109	                BigDecimal amountPaid = new BigDecimal("0");
110	
111	                try {
112	                    String body = ctx.body();
113	                    if (body != null && !body.isEmpty()) {
114	                        var json = gson.fromJson(body, java.util.Map.class);
115	                        if (json.containsKey("amountPaid")) {
116	                            amountPaid = new BigDecimal(json.get("amountPaid").toString());
117	                        }
118	                    }
119	                } catch (Exception ignored) {}
120	
121	                var reservation = reservationService.confirmReservation(id, amountPaid);
122	                ctx.json(ReservationResponse.from(reservation));
123	            } catch (ApiException e) {
124	                handleError(ctx, e.getCode(), e.getMessage(), e.getHttpStatus());
125	            } catch (Exception e) {
126	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
127	            }
128	        });
129	
130	        app.post("/reservations/{id}/check-in", ctx -> {
131	            try {
132	                long id = Long.parseLong(ctx.pathParam("id"));
133	                var reservation = reservationService.checkIn(id);
134	                ctx.json(ReservationResponse.from(reservation));
135	            } catch (ApiException e) {
136	                handleError(ctx, e.getCode(), e.getMessage(), e.getHttpStatus());
137	            } catch (Exception e) {
138	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
139	            }
140	        });
141	
142	        app.post("/reservations/{id}/check-out", ctx -> {
143	            try {
144	                long id = Long.parseLong(ctx.pathParam("id"));
145	                var reservation = reservationService.checkOut(id);
146	                var room = new RoomRepository().findByNumber(reservation.getRoomNumber());
147	                ctx.json(ReceiptResponse.from(reservation, room));
148	            } catch (ApiException e) {
149	                handleError(ctx, e.getCode(), e.getMessage(), e.getHttpStatus());
150	            } catch (Exception e) {
151	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
152	            }
153	        });
154	
155	        app.post("/reservations/{id}/cancellation", ctx -> {
156	            try {
157	                long id = Long.parseLong(ctx.pathParam("id"));
158	                var reservation = reservationService.cancelReservation(id);
159	                ctx.json(ReservationResponse.from(reservation));
160	            } catch (ApiException e) {
161	                handleError(ctx, e.getCode(), e.getMessage(), e.getHttpStatus());
162	            } catch (Exception e) {
163	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
164	            }
165	        });
166	
167	        app.get("/reservations/{id}/document", ctx -> {
168	            try {
169	                long id = Long.parseLong(ctx.pathParam("id"));
170	                var reservation = reservationService.getReservation(id);
171	
172	                if (reservation.getAmountPaid().signum() == 0) {
173	                    handleError(ctx, "OPERATION_NOT_ALLOWED", "Documento disponível apenas para reservas pagas", 409);
174	                    return;
175	                }
176	
177	                var room = new RoomRepository().findByNumber(reservation.getRoomNumber());
178	                ctx.json(ReceiptResponse.from(reservation, room));
179	            } catch (ApiException e) {
180	                handleError(ctx, e.getCode(), e.getMessage(), e.getHttpStatus());
181	            } catch (Exception e) {
182	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
183	            }
184	        });
185	
186	        app.get("/messages", ctx -> {
187	            try {
188	                var messages = messageRepository.findAll();
189	                ctx.json(messages.stream().map(MessageResponse::from).toList());
190	            } catch (Exception e) {
191	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
192	            }
193	        });
194	
195	        app.get("/reports/occupancy", ctx -> {
196	            try {
197	                String dateStr = ctx.queryParam("date");
198	                if (dateStr == null) {
199	                    handleError(ctx, "INVALID_REQUEST", "Parâmetro 'date' obrigatório", 400);
200	                    return;
201	                }
202	
203	                try {
204	                    LocalDate date = LocalDate.parse(dateStr);
205	                    String report = reportService.generateOccupancyReport(date);
206	                    ctx.contentType("text/csv; charset=utf-8").result(report);
207	                } catch (DateTimeParseException e) {
208	                    handleError(ctx, "INVALID_REQUEST", "Formato de data inválido", 400);
209	                }
210	            } catch (Exception e) {
211	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
212	            }
213	        });
214	
215	        app.get("/reports/revenue", ctx -> {
216	            try {
217	                String monthStr = ctx.queryParam("month");
218	                if (monthStr == null) {
219	                    handleError(ctx, "INVALID_REQUEST", "Parâmetro 'month' obrigatório", 400);
220	                    return;
221	                }
222	
223	                try {
224	                    YearMonth month = YearMonth.parse(monthStr);
225	                    String report = reportService.generateRevenueReport(month);
226	                    ctx.contentType("text/csv; charset=utf-8").result(report);
227	                } catch (DateTimeParseException e) {
228	                    handleError(ctx, "INVALID_REQUEST", "Formato de mês inválido", 400);
229	                }
230	            } catch (Exception e) {
231	                handleError(ctx, "INTERNAL_ERROR", e.getMessage(), 500);
232	            }
233	        });
234	    }
235	
236	    private static void handleError(io.javalin.http.Context ctx, String code, String message, int status) {
237	        ctx.status(status).json(new java.util.HashMap<String, Object>() {{
238	            put("error", code);
239	            put("message", message);
240	        }});
241	    }
242	}
