263	package com.pousada.service;
264	
265	import com.pousada.domain.Reservation;
266	import com.pousada.domain.Room;
267	import com.pousada.domain.ReservationStatus;
268	import com.pousada.infra.ReservationRepository;
269	import com.pousada.infra.RoomRepository;
270	import java.math.BigDecimal;
271	import java.sql.SQLException;
272	import java.time.LocalDate;
273	import java.time.YearMonth;
274	import java.util.List;
275	
276	public class ReportService {
277	    private final ReservationRepository reservationRepository;
278	    private final RoomRepository roomRepository;
279	
280	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
281	        this.reservationRepository = reservationRepository;
282	        this.roomRepository = roomRepository;
283	    }
284	
285	    public String generateOccupancyReport(LocalDate date) throws SQLException {
286	        List<Room> allRooms = roomRepository.findAll();
287	        StringBuilder csv = new StringBuilder();
288	        csv.append("room,type,reservation,check_in,check_out\n");
289	
290	        int occupiedCount = 0;
291	
292	        for (Room room : allRooms) {
293	            var reservations = reservationRepository.findByRoomAndDateRange(room.getNumber(), date, date.plusDays(1));
294	
295	            boolean occupied = false;
296	            for (Reservation res : reservations) {
297	                if (res.getStatus() == ReservationStatus.CONFIRMED ||
298	                    res.getStatus() == ReservationStatus.CHECKED_IN ||
299	                    res.getStatus() == ReservationStatus.CHECKED_OUT) {
300	
301	                    csv.append(room.getNumber()).append(",")
302	                       .append(room.getType()).append(",")
303	                       .append(res.getId()).append(",")
304	                       .append(formatDate(res.getCheckIn())).append(",")
305	                       .append(formatDate(res.getCheckOut())).append("\n");
306	                    occupied = true;
307	                }
308	            }
309	
310	            if (occupied) {
311	                occupiedCount++;
312	            }
313	        }
314	
315	        csv.append("total,").append(occupiedCount).append("/").append(allRooms.size()).append("\n");
316	        return csv.toString();
317	    }
318	
319	    public String generateRevenueReport(YearMonth month) throws SQLException {
320	        List<Reservation> reservations = reservationRepository.findByMonthAndPaid(month.getYear(), month.getMonthValue());
321	
322	        StringBuilder csv = new StringBuilder();
323	        csv.append("reservation,room,check_in,check_out,status,amount\n");
324	
325	        BigDecimal total = BigDecimal.ZERO;
326	
327	        for (Reservation res : reservations) {
328	            BigDecimal amount = res.getAmountPaid();
329	            if (res.getRefund() != null) {
330	                amount = amount.subtract(res.getRefund());
331	            }
332	
333	            csv.append(res.getId()).append(",")
334	               .append(res.getRoomNumber()).append(",")
335	               .append(formatDateForCsv(res.getCheckIn())).append(",")
336	               .append(formatDateForCsv(res.getCheckOut())).append(",")
337	               .append(res.getStatus()).append(",")
338	               .append(formatMoneyForCsv(amount)).append("\n");
339	
340	            total = total.add(amount);
341	        }
342	
343	        csv.append("total,").append(formatMoneyForCsv(total)).append("\n");
344	        return csv.toString();
345	    }
346	
347	    private String formatDate(LocalDate date) {
348	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
349	    }
350	
351	    private String formatDateForCsv(LocalDate date) {
352	        return String.format("%04d-%02d-%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
353	    }
354	
355	    private String formatMoneyForCsv(BigDecimal amount) {
356	        return String.format("%.2f", amount);
357	    }
358	}
359	package com.pousada.service;
360	
361	import com.pousada.domain.Reservation;
362	import com.pousada.domain.ReservationStatus;
363	import com.pousada.domain.Room;
364	import com.pousada.domain.rateplans.CorporateRatePlan;
365	import com.pousada.domain.rateplans.InvalidReservationException;
366	import com.pousada.domain.rateplans.RatePlan;
367	import com.pousada.domain.rateplans.RatePlanRegistry;
368	import com.pousada.infra.MessageRepository;
369	import com.pousada.infra.ReservationRepository;
370	import com.pousada.infra.RoomRepository;
371	import java.math.BigDecimal;
372	import java.sql.SQLException;
373	import java.text.DecimalFormat;
374	import java.text.DecimalFormatSymbols;
375	import java.time.LocalDate;
376	
377	public class ReservationService {
378	    private final RoomRepository roomRepository;
379	    private final ReservationRepository reservationRepository;
380	    private final MessageRepository messageRepository;
381	
382	    public ReservationService(RoomRepository roomRepository, ReservationRepository reservationRepository,
383	                             MessageRepository messageRepository) {
384	        this.roomRepository = roomRepository;
385	        this.reservationRepository = reservationRepository;
386	        this.messageRepository = messageRepository;
387	    }
388	
389	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
390	                                         LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan,
391	                                         String companyCode) throws SQLException {
392	        if (guests < 1) {
393	            throw new ApiException("INVALID_REQUEST", "Reserva deve ter pelo menos 1 hóspede", 400);
394	        }
395	
396	        if (checkIn.isAfter(checkOut) || checkIn.equals(checkOut)) {
397	            throw new ApiException("INVALID_REQUEST", "Data de saída deve ser após a entrada", 400);
398	        }
399	
400	        Room room = roomRepository.findByNumber(roomNumber);
401	        if (room == null) {
402	            throw new ApiException("ROOM_NOT_FOUND", "Quarto não encontrado", 404);
403	        }
404	
405	        if (guests > room.getCapacity()) {
406	            throw new ApiException("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade do quarto", 422);
407	        }
408	
409	        if (!RatePlanRegistry.exists(ratePlan)) {
410	            throw new ApiException("INVALID_REQUEST", "Plano de tarifa inválido", 400);
411	        }
412	
413	        RatePlan plan = RatePlanRegistry.get(ratePlan);
414	        try {
415	            plan.validate(roomNumber, checkIn, checkOut, guests, companyCode);
416	        } catch (InvalidReservationException e) {
417	            throw new ApiException(e.getCode(), e.getMessage(), 400);
418	        }
419	
420	        var conflictingReservations = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
421	        if (!conflictingReservations.isEmpty()) {
422	            throw new ApiException("ROOM_UNAVAILABLE", "Quarto não disponível nas datas solicitadas", 409);
423	        }
424	
425	        RatePlan.PriceCalculation priceCalc;
426	        if (plan instanceof CorporateRatePlan corpPlan) {
427	            priceCalc = corpPlan.calculatePrice(room, checkIn, checkOut, companyCode);
428	        } else {
429	            priceCalc = plan.calculatePrice(room, checkIn, checkOut);
430	        }
431	
432	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
433	
434	        Reservation reservation = new Reservation(
435	            0,
436	            roomNumber,
437	            guestName,
438	            guestEmail,
439	            guestCpf,
440	            checkIn,
441	            checkOut,
442	            guests,
443	            ratePlan,
444	            companyCode,
445	            nights,
446	            priceCalc.subtotal(),
447	            priceCalc.discount(),
448	            priceCalc.total(),
449	            ReservationStatus.PENDING,
450	            BigDecimal.ZERO,
451	            null
452	        );
453	
454	        return reservationRepository.save(reservation);
455	    }
456	
457	    public Reservation getReservation(long id) throws SQLException {
458	        Reservation reservation = reservationRepository.findById(id);
459	        if (reservation == null) {
460	            throw new ApiException("RESERVATION_NOT_FOUND", "Reserva não encontrada", 404);
461	        }
462	        return reservation;
463	    }
464	
465	    public Reservation confirmReservation(long id, BigDecimal amountPaid) throws SQLException {
466	        Reservation reservation = getReservation(id);
467	        if (reservation.getStatus() != ReservationStatus.PENDING) {
468	            throw new ApiException("OPERATION_NOT_ALLOWED", "Apenas reservas pendentes podem ser confirmadas", 409);
469	        }
470	
471	        reservationRepository.updateConfirmation(id, ReservationStatus.CONFIRMED, amountPaid);
472	        reservation = getReservation(id);
473	
474	        sendConfirmationEmail(reservation);
475	
476	        return reservation;
477	    }
478	
479	    public Reservation checkIn(long id) throws SQLException {
480	        Reservation reservation = getReservation(id);
481	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
482	            throw new ApiException("OPERATION_NOT_ALLOWED", "Apenas reservas confirmadas podem fazer check-in", 409);
483	        }
484	
485	        reservationRepository.updateStatus(id, ReservationStatus.CHECKED_IN);
486	        return getReservation(id);
487	    }
488	
489	    public Reservation checkOut(long id) throws SQLException {
490	        Reservation reservation = getReservation(id);
491	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
492	            throw new ApiException("OPERATION_NOT_ALLOWED", "Apenas reservas com check-in podem fazer check-out", 409);
493	        }
494	
495	        reservationRepository.updateStatus(id, ReservationStatus.CHECKED_OUT);
496	        return getReservation(id);
497	    }
498	
499	    public Reservation cancelReservation(long id) throws SQLException {
500	        Reservation reservation = getReservation(id);
501	        if (reservation.getStatus() == ReservationStatus.CHECKED_OUT ||
502	            reservation.getStatus() == ReservationStatus.CANCELLED) {
503	            throw new ApiException("OPERATION_NOT_ALLOWED", "Reserva não pode ser cancelada", 409);
504	        }
505	
506	        RatePlan plan = RatePlanRegistry.get(reservation.getRatePlan());
507	        BigDecimal refund = plan.calculateRefund(reservation.getAmountPaid());
508	
509	        reservationRepository.updateCancellation(id, refund);
510	        return getReservation(id);
511	    }
512	
513	    private void sendConfirmationEmail(Reservation reservation) throws SQLException {
514	        Room room = roomRepository.findByNumber(reservation.getRoomNumber());
515	        String receipt = generateReceipt(reservation, room);
516	
517	        String subject = "Reserva confirmada - Pousada Maré Alta";
518	        String body = formatConfirmationEmail(reservation, receipt);
519	
520	        messageRepository.save("EMAIL", reservation.getGuestEmail(), subject, body);
521	    }
522	
523	    public String generateReceipt(Reservation reservation, Room room) {
524	        StringBuilder sb = new StringBuilder();
525	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
526	        sb.append("Hóspede: ").append(reservation.getGuestName()).append(" (CPF ").append(formatCPF(reservation.getGuestCpf())).append(")\n");
527	        sb.append("Quarto: ").append(reservation.getRoomNumber()).append(" (").append(room.getType()).append(")\n");
528	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn())).append(" | ");
529	        sb.append("Saída: ").append(formatDate(reservation.getCheckOut())).append(" | ");
530	        sb.append(reservation.getNights()).append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
531	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
532	
533	        if (reservation.getDiscount().signum() > 0) {
534	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
535	        }
536	
537	        sb.append("Total: ").append(formatMoney(reservation.getTotal())).append("\n");
538	        return sb.toString();
539	    }
540	
541	    private String formatConfirmationEmail(Reservation reservation, String receipt) {
542	        StringBuilder sb = new StringBuilder();
543	        sb.append("Olá, ").append(reservation.getGuestName()).append("!\n\n");
544	        sb.append("Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n");
545	        sb.append(receipt).append("\n");
546	        sb.append("A entrada é a partir das 14h, e a saída, até as 12h.\n");
547	        sb.append("Até breve!");
548	        return sb.toString();
549	    }
550	
551	    public String formatDate(LocalDate date) {
552	        return String.format("%02d/%02d/%04d", date.getDayOfMonth(), date.getMonthValue(), date.getYear());
553	    }
554	
555	    public String formatMoney(BigDecimal amount) {
556	        var symbols = new java.text.DecimalFormatSymbols();
557	        symbols.setDecimalSeparator(',');
558	        symbols.setGroupingSeparator('.');
559	        var df = new java.text.DecimalFormat("#,##0.00", symbols);
560	        return "R$ " + df.format(amount);
561	    }
562	
563	    public String formatCPF(String cpf) {
564	        if (cpf.length() != 11) return cpf;
565	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
566	    }
567	}

