    10	public class WeekendPackageRatePlan extends BaseRatePlan {
    11	    private static final Map<Room.RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
    12	        Room.RoomType.STANDARD, new BigDecimal("520.00"),
    13	        Room.RoomType.DELUXE, new BigDecimal("820.00"),
    14	        Room.RoomType.SUITE, new BigDecimal("1200.00")
    15	    );
