    22	    @Override
    23	    public void validate(int roomNumber, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
    24	        validateBasic(guests);
    25	
    26	        if (checkIn.getDayOfWeek() != DayOfWeek.FRIDAY) {
    27	            throw new InvalidReservationException("INVALID_REQUEST", "Pacote de fim de semana deve começar numa sexta");
    28	        }
    29	
    30	        LocalDate expectedCheckOut = checkIn.plusDays(2);
    31	        if (!checkOut.equals(expectedCheckOut)) {
    32	            throw new InvalidReservationException("INVALID_REQUEST", "Pacote de fim de semana deve ter exatamente 2 noites");
    33	        }
    34	
    35	        if (checkOut.getDayOfWeek() != DayOfWeek.SUNDAY) {
    36	            throw new InvalidReservationException("INVALID_REQUEST", "Pacote de fim de semana deve terminar num domingo");
    37	        }
    38	    }
    39	
    40	    @Override
    41	    public PriceCalculation calculatePrice(Room room, LocalDate checkIn, LocalDate checkOut) {
    42	        BigDecimal price = PACKAGE_PRICES.get(room.getType());
    43	        return new PriceCalculation(price, BigDecimal.ZERO, price);
    44	    }
