     1	package com.pousada.infra;
     2	
     3	import java.sql.Connection;
     4	import java.sql.DriverManager;
     5	import java.sql.SQLException;
     6	
     7	public class Database {
     8	    private static final String DB_URL = System.getenv("DB_URL");
     9	    private static final String DB_USER = System.getenv("DB_USER");
    10	    private static final String DB_PASSWORD = System.getenv("DB_PASSWORD");
    11	
    12	    static {
    13	        try {
    14	            Class.forName("org.postgresql.Driver");
    15	        } catch (ClassNotFoundException e) {
    16	            throw new RuntimeException("PostgreSQL driver not found", e);
    17	        }
    18	    }
    19	
    20	    public static Connection getConnection() throws SQLException {
    21	        if (DB_URL == null || DB_USER == null || DB_PASSWORD == null) {
    22	            throw new RuntimeException("Database environment variables not configured");
    23	        }
    24	        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    25	    }
    26	
    27	    public static void initializeSchema() {
    28	        try (Connection conn = getConnection();
    29	             var stmt = conn.createStatement()) {
    30	
    31	            stmt.execute("""
    32	                CREATE TABLE IF NOT EXISTS rooms (
    33	                    number INT PRIMARY KEY,
    34	                    type VARCHAR(20) NOT NULL,
    35	                    capacity INT NOT NULL,
    36	                    nightly_rate NUMERIC(10, 2) NOT NULL
    37	                )
    38	            """);
    39	
    40	            stmt.execute("""
    41	                CREATE TABLE IF NOT EXISTS reservations (
    42	                    id BIGSERIAL PRIMARY KEY,
    43	                    room_number INT NOT NULL,
    44	                    guest_name VARCHAR(255) NOT NULL,
    45	                    guest_email VARCHAR(255) NOT NULL,
    46	                    guest_cpf VARCHAR(14) NOT NULL,
    47	                    check_in DATE NOT NULL,
    48	                    check_out DATE NOT NULL,
    49	                    guests INT NOT NULL,
    50	                    rate_plan VARCHAR(50) NOT NULL,
    51	                    company_code VARCHAR(50),
    52	                    nights INT NOT NULL,
    53	                    subtotal NUMERIC(10, 2) NOT NULL,
    54	                    discount NUMERIC(10, 2) NOT NULL,
    55	                    total NUMERIC(10, 2) NOT NULL,
    56	                    status VARCHAR(20) NOT NULL,
    57	                    amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0,
    58	                    refund NUMERIC(10, 2),
    59	                    FOREIGN KEY (room_number) REFERENCES rooms(number)
    60	                )
    61	            """);
    62	
    63	            stmt.execute("""
    64	                CREATE TABLE IF NOT EXISTS messages (
    65	                    id BIGSERIAL PRIMARY KEY,
    66	                    channel VARCHAR(50) NOT NULL,
    67	                    recipient VARCHAR(255) NOT NULL,
    68	                    subject VARCHAR(255) NOT NULL,
    69	                    body TEXT NOT NULL,
    70	                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    71	                )
    72	            """);
    73	
    74	            insertInitialRooms(conn);
    75	        } catch (SQLException e) {
    76	            throw new RuntimeException("Failed to initialize database schema", e);
    77	        }
    78	    }
    79	
    80	    private static void insertInitialRooms(Connection conn) throws SQLException {
    81	        try (var stmt = conn.createStatement()) {
    82	            stmt.execute("DELETE FROM rooms");
    83	            stmt.execute("""
    84	                INSERT INTO rooms VALUES
