    86	                (102, 'STANDARD', 2, 249.90),
    87	                (201, 'DELUXE', 3, 389.90),
    88	                (202, 'DELUXE', 3, 389.90),
    89	                (301, 'SUITE', 4, 579.90)
    90	            """);
    91	        }
